contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(address target) public payable {
        require(target != address(0), "target must be nonzero");

        uint beforeCount = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint beforeBalance = address(c).balance;

        c.sendMoney(target, 0); if (__ESBMC_reverted()) return;

        uint afterCount = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint afterBalance = address(c).balance;

        assert(afterCount == beforeCount && afterBalance == beforeBalance);
    }

    fallback() external payable {}
}

